interface Attribute {
	name: string;
	value: any;
	dynamic: boolean;
	dependencies?: string[]
}

interface Binding {
	name: string;
	value: Node;
	contexts: Set<string>;
	snippet: string;
	obj: string;
	prop: string;
	dependencies: string[];
}

export default function visitComponent(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
