		? generator.name
		: generator.importedComponents.get(node.name) ||
				`@template.components.${node.name}`;

	block.builders.init.addBlock(deindent`
		${statements.join('\n')}
		var ${name} = new ${expression}({
			${componentInitProperties.join(',\n')}
		});

		${beforecreate}
	`);

